        # Fault101. Received A Response From API With A Structure/Data That Is Not Matching Its Schema. Type: validation.response.status.unknown Response status 401 not defined for path '/api/v1/agents/{agent_id}'.
        headers = {}
        headers["Authorization"] = auth_victim # victim
        headers['Accept'] = "application/json"
        res_3 = requests \
                .delete(self.baseUrlOfSut + "/api/v1/agents/DgUCyq9",
                    headers=headers, timeout=EM_HTTP_TIMEOUT_S, verify=False)
        
        assert res_3.status_code == 401
        assert "Bearer" in res_3.headers["www-authenticate"]
        assert "application/json" in res_3.headers["content-type"]
        assert res_3.json()["detail"] == "Invalid or expired session"
        
        # Fault101. Received A Response From API With A Structure/Data That Is Not Matching Its Schema. Type: validation.response.status.unknown Response status 401 not defined for path '/api/v1/resources'.
        headers = {}
        headers["Authorization"] = auth_victim # victim
        headers['Accept'] = "application/json"
        res_4 = requests \
                .get(self.baseUrlOfSut + "/api/v1/resources",
                    headers=headers, timeout=EM_HTTP_TIMEOUT_S, verify=False)
        
        assert res_4.status_code == 401
        assert "Bearer" in res_4.headers["www-authenticate"]
        assert "application/json" in res_4.headers["content-type"]
        assert res_4.json()["detail"] == "Invalid or expired session"
        
        headers = {}
        headers["Authorization"] = auth_viewer # viewer
        headers['Accept'] = "application/json"
        res_5 = requests \
                .get(self.baseUrlOfSut + "/api/v1/resources",
                    headers=headers, timeout=EM_HTTP_TIMEOUT_S, verify=False)
        
        assert res_5.status_code == 200
        assert "application/json" in res_5.headers["content-type"]
        assert len(res_5.json()["resources"]) == 0
        
        # Fault101. Received A Response From API With A Structure/Data That Is Not Matching Its Schema. Type: validation.response.status.unknown Response status 401 not defined for path '/api/v1/agents/{agent_id}/instance/{instance_id}/offline'.
        # Fault205. Wrongly Not Recognized as Authenticated.
        headers = {}
        headers["Authorization"] = auth_viewer # viewer
        headers['Accept'] = "application/json"
        res_6 = requests \
                .post(self.baseUrlOfSut + "/api/v1/agents/SI9H/instance/qSSaeZ5BT/offline",
                    headers=headers, timeout=EM_HTTP_TIMEOUT_S, verify=False)
        
        assert res_6.status_code == 401
        assert "www-authenticate" not in res_6.headers
        assert "application/json" in res_6.headers["content-type"]
        assert res_6.json()["detail"] == "Missing X-Bamf-Client-Cert header"


